using System; using System.Collections.Generic; using System.Linq; using Avalonia; using Avalonia.Controls; using Avalonia.Layout; using Avalonia.Media; using Kreta.Core; using Kreta.Contexts; namespace Kreta.Dynamic; public class SubjectAveragesView_e81e3a1f : UserControl, IEvolView { public string Name => "Tantárgyi átlagaim"; public string Description => "Egy panel, ami tantárgyakra bontva mutatja a jegyeid átlagát."; private readonly IStudentContext? _context; public SubjectAveragesView_e81e3a1f() { } public SubjectAveragesView_e81e3a1f(IStudentContext context) { _context = context; } public Control CreateView() { if (_context is null) { return new TextBlock { Text = "Hiba: A student kontextus nem elérhető.", HorizontalAlignment = HorizontalAlignment.Center, VerticalAlignment = VerticalAlignment.Center }; } var grades = _context.GetMyGrades(); if (grades == null || !grades.Any()) { return new TextBlock { Text = "Még nincsenek rögzített jegyeid.", HorizontalAlignment = HorizontalAlignment.Center, VerticalAlignment = VerticalAlignment.Center }; } var averagesBySubject = grades.Where(g => g.Subject != null).GroupBy(g => g.Subject.Name).Select(group => new { SubjectName = group.Key, Average = group.Average(g => g.Value) }).OrderBy(a => a.SubjectName).ToList(); var mainPanel = new StackPanel { Margin = new Thickness(15), Spacing = 10 }; mainPanel.Children.Add(new TextBlock { Text = "Tantárgyi átlagok", FontSize = 20, FontWeight = FontWeight.Bold, HorizontalAlignment = HorizontalAlignment.Center }); var grid = new Grid { ColumnDefinitions = new ColumnDefinitions("*, Auto") }; int rowIndex = 0; foreach (var item in averagesBySubject) { grid.RowDefinitions.Add(new RowDefinition(GridLength.Auto)); var subjectLabel = new TextBlock { Text = item.SubjectName, VerticalAlignment = VerticalAlignment.Center }; Grid.SetRow(subjectLabel, rowIndex); Grid.SetColumn(subjectLabel, 0); var averageLabel = new TextBlock { Text = item.Average.ToString("F2"), FontWeight = FontWeight.Bold, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(20, 0, 0, 0) }; Grid.SetRow(averageLabel, rowIndex); Grid.SetColumn(averageLabel, 1); var border = new Border { Background = Brushes.LightGray, CornerRadius = new CornerRadius(5), Padding = new Thickness(10), Margin = new Thickness(0, 0, 0, 5) }; var itemGrid = new Grid { ColumnDefinitions = new ColumnDefinitions("*,Auto") }; itemGrid.Children.Add(subjectLabel); itemGrid.Children.Add(averageLabel); border.Child = itemGrid; mainPanel.Children.Add(border); rowIndex++; } return new ScrollViewer { Content = mainPanel }; } }